import{_ as a,a0 as l,w as u,s as r,I as i,x as n,a1 as e,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux 初學者：如何在 Ubuntu 中重啓網絡 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 初學者：如何在 Ubuntu 中重啓網絡 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 初學者：如何在 Ubuntu 中重啓網絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 初學者：如何在 Ubuntu 中重啓網絡 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190307 How to Restart a Network in Ubuntu -Beginner-s Tip","title":"Linux 初學者：如何在 Ubuntu 中重啓網絡","tag":"201905","desc":""},"relativePath":"201905/20190307 How to Restart a Network in Ubuntu -Beginner-s Tip.md","filePath":"[post].md"}'),d={name:"201905/20190307 How to Restart a Network in Ubuntu -Beginner-s Tip.md"};function m(g,t,f,c,h,b){const s=l("Link");return u(),r("div",null,[t[29]||(t[29]=i("h1",{id:"linux-初學者-如何在-ubuntu-中重啓網絡",tabindex:"-1"},[n("Linux 初學者：如何在 Ubuntu 中重啓網絡 "),i("a",{class:"header-anchor",href:"#linux-初學者-如何在-ubuntu-中重啓網絡","aria-label":"Permalink to “Linux 初學者：如何在 Ubuntu 中重啓網絡”"},"​")],-1)),i("p",null,[t[1]||(t[1]=n("你",-1)),e(s,{href:"https://itsfoss.com/fix-no-wireless-network-ubuntu/"},{default:o(()=>[...t[0]||(t[0]=[n("是否正在使用基於 Ubuntu 的系統，然後發現無法連接網絡",-1)])]),_:1}),t[2]||(t[2]=n("？你一定會很驚訝，很多的問題都可以簡單地通過重啓服務解決。",-1))]),t[30]||(t[30]=i("p",null,"在這篇文章中，我會介紹在 Ubuntu 或者其他 Linux 發行版中重啓網絡的幾種方法，你可以根據自身需要選擇對應的方法。這些方法基本分為兩類：",-1)),t[31]||(t[31]=i("p",null,[i("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/ubuntu-restart-network.png?resize=800%2C450&ssl=1",alt:"Ubuntu Restart Network"})],-1)),t[32]||(t[32]=i("h3",{id:"通過命令列方式重啓網絡",tabindex:"-1"},[n("通過命令列方式重啓網絡 "),i("a",{class:"header-anchor",href:"#通過命令列方式重啓網絡","aria-label":"Permalink to “通過命令列方式重啓網絡”"},"​")],-1)),i("p",null,[t[4]||(t[4]=n("如果你使用的 Ubuntu 服務器版，那麼你已經在使用命令列終端了。如果你使用的是桌面版，那麼你可以通過快捷鍵 ",-1)),t[5]||(t[5]=i("code",null,"Ctrl+Alt+T",-1)),t[6]||(t[6]=n()),e(s,{href:"https://itsfoss.com/ubuntu-shortcuts/"},{default:o(()=>[...t[3]||(t[3]=[n("Ubuntu 鍵盤快捷鍵",-1)])]),_:1}),t[7]||(t[7]=n(" 打開命令列終端。",-1))]),t[33]||(t[33]=p('<p>在 Ubuntu 中，有多個命令可以重啓網絡。這些命令，一部分或者説大部分，也適用於在 Debian 或者其他的 Linux 發行版中重啓網絡。</p><h4 id="_1、network-manager-服務" tabindex="-1">1、network manager 服務 <a class="header-anchor" href="#_1、network-manager-服務" aria-label="Permalink to “1、network manager 服務”">​</a></h4><p>這是通過命令列方式重啓網絡最簡單的方法。它相當於是通過圖形化界面重啓網絡（重啓 Network-Manager 服務）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service network-manager restart</span></span></code></pre></div><p>此時，網絡圖標會消失一會兒然後重新顯示。</p><h4 id="_2、systemd" tabindex="-1">2、systemd <a class="header-anchor" href="#_2、systemd" aria-label="Permalink to “2、systemd”">​</a></h4><p><code>service</code> 命令僅僅是這個方式的一個封裝（同樣的也是 init.d 系列腳本和 Upstart 相關命令的封裝）。<code>systemctl</code> 命令的功能遠多於 <code>service</code> 命令。通常我更喜歡使用這個命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart NetworkManager.service</span></span></code></pre></div><p>這時，網絡圖標又會消失一會兒。 如果你想了解 <code>systemctl</code> 的其他選項, 可以參考 man 幫助文檔。</p><h4 id="_3、nmcli" tabindex="-1">3、nmcli <a class="header-anchor" href="#_3、nmcli" aria-label="Permalink to “3、nmcli”">​</a></h4><p>這是 Linux 上可以管理網絡的另一個工具。這是一個功能強大而且實用的工具。很多系統管理員都喜歡使用該工具，因為它非常容易使用。</p><p>這種方法有兩個操作步驟：關閉網絡，再開啓網絡。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nmcli networking off</span></span></code></pre></div><p>這樣就會關閉網絡，網絡圖標會消失。接下來，再開啓網絡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nmcli networking on</span></span></code></pre></div><p>你可以通過 man 幫助文檔瞭解 nmcli 的更多用法。</p><h4 id="_4、ifup-ifdown" tabindex="-1">4、ifup &amp; ifdown <a class="header-anchor" href="#_4、ifup-ifdown" aria-label="Permalink to “4、ifup &amp; ifdown”">​</a></h4>',17)),i("p",null,[t[9]||(t[9]=n("這兩個命令直接操作網口，切換網口是否可以收發包的狀態。這是 ",-1)),e(s,{href:"https://itsfoss.com/basic-linux-networking-commands/"},{default:o(()=>[...t[8]||(t[8]=[n("Linux 中最應該瞭解的網絡命令",-1)])]),_:1}),t[10]||(t[10]=n(" 之一。",-1))]),t[34]||(t[34]=p('<p>使用 <code>ifdown</code> 關閉所有網口，再使用 <code>ifup</code> 重新啓用網口。</p><p>通常推薦的做法是將這兩個命令一起使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ifdown -a &amp;&amp; sudo ifup -a</span></span></code></pre></div><p>注意：這種方法不會讓網絡圖標從系統托盤中消失，另外，各種網絡連接也會斷。</p><h4 id="補充工具-nmtui" tabindex="-1">補充工具： nmtui <a class="header-anchor" href="#補充工具-nmtui" aria-label="Permalink to “補充工具： nmtui”">​</a></h4><p>這是系統管理員們常用的另外一種方法。它是在命令列終端中管理網絡的文本菜單工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmtui</span></span></code></pre></div><p>打開如下菜單：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmtui_menu.png?fit=800%2C602&amp;ssl=1" alt="nmtui Menu"></p><p>注意：在 nmtui 中，可以通過 <code>up</code> 和 <code>down</code> 方向鍵選擇選項。</p><p>選擇 “Activate a connection”：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmtui_menu_select_option.png?fit=800%2C579&amp;ssl=1" alt="nmtui Menu Select &quot;Activate a connection&quot;"></p><p>按下回車鍵，打開 “connections” 菜單。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_on.png?fit=800%2C585&amp;ssl=1" alt="nmtui Connections Menu"></p><p>接下來，選擇前面帶星號（*）的網絡。在這個例子中，就是 MGEO72。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_select_connection_on.png?fit=800%2C576&amp;ssl=1" alt="Select your connection in the nmtui connections menu."></p><p>按下回車鍵。 這就將“停用”你的網絡連接。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_off.png?fit=800%2C572&amp;ssl=1" alt="nmtui Connections Menu with no active connection"></p><p>選擇你要連接的網絡：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_select_connection_off.png?fit=800%2C566&amp;ssl=1" alt="Select the connection you want in the nmtui connections menu."></p><p>按下回車鍵。這樣就重新激活了所選擇的網絡連接。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_on-1.png?fit=800%2C585&amp;ssl=1" alt="nmtui Connections Menu"></p><p>按下 <code>Tab</code> 鍵兩次，選擇 “Back”：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_connection_menu_back.png?fit=800%2C585&amp;ssl=1" alt="Select &quot;Back&quot; in the nmtui connections menu."></p><p>按下回車鍵，回到 nmtui 的主菜單。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmtui_menu_select_option-1.png?fit=800%2C579&amp;ssl=1" alt="nmtui Main Menu"></p><p>選擇 “Quit” ：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/nmui_menu_quit.png?fit=800%2C580&amp;ssl=1" alt="nmtui Quit Main Menu"></p><p>退出該界面，返回到命令列終端。</p><p>就這樣，你已經成功重啓網絡了。</p><h3 id="通過圖形化界面重啓網絡" tabindex="-1">通過圖形化界面重啓網絡 <a class="header-anchor" href="#通過圖形化界面重啓網絡" aria-label="Permalink to “通過圖形化界面重啓網絡”">​</a></h3><p>顯然，這是 Ubuntu 桌面版用户重啓網絡最簡單的方法。如果這個方法不生效，你可以嘗試使用前文提到的命令列方式重啓網絡。</p>',32)),i("p",null,[t[12]||(t[12]=n("NM 小程序是 ",-1)),e(s,{href:"https://wiki.gnome.org/Projects/NetworkManager"},{default:o(()=>[...t[11]||(t[11]=[n("NetworkManager",-1)])]),_:1}),t[13]||(t[13]=n(" 的系統托盤程序標誌。我們將使用它來重啓網絡。",-1))]),t[35]||(t[35]=p('<p>首先，查看頂部狀態欄。你會在系統托盤找到一個網絡圖標 （因為我使用 Wi-Fi，所以這裏是一個 Wi-Fi 圖標）。</p><p>接下來，點擊該圖標（也可以點擊音量圖標或電池圖標）。打開菜單。選擇 “Turn Off” 關閉網絡。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/restart-network-ubuntu-1.jpg?resize=800%2C400&amp;ssl=1" alt="Restart network in Ubuntu"></p><p>網絡圖標會在狀態欄中消失，這表示你已經成功關閉網絡了。</p><p>再次點擊系統托盤重新打開菜單，選擇 “Turn On”，重新開啓網絡。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/restart-network-ubuntu-2.jpg?resize=800%2C400&amp;ssl=1" alt="Restarting network in Ubuntu"></p><p>恭喜！你現在已經重啓你的網絡了。</p><h4 id="其他提示-刷新可用網絡列表" tabindex="-1">其他提示：刷新可用網絡列表 <a class="header-anchor" href="#其他提示-刷新可用網絡列表" aria-label="Permalink to “其他提示：刷新可用網絡列表”">​</a></h4><p>如果你已經連接上一個網絡，但是你想連接到另外一個網絡，你如何刷新 WiFi 列表，查找其他可用的網絡呢？我來向你展示一下。</p><p>Ubuntu 沒有可以直接 “刷新 WiFi 網絡” 的選項，它有點隱蔽。</p><p>你需要再次打開配置菜單，然後點擊 “Select Network” 。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/03/select-wifi-network-ubuntu.jpg?resize=800%2C400&amp;ssl=1" alt="Refresh wifi network list in Ubuntu"></p><p>選擇對應的網絡修改你的 WiFi 連接。</p><p>你無法馬上看到可用的無線網絡列表。打開網絡列表之後，大概需要 5 秒才會顯示其它可用的無線網絡。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/select-wifi-network-ubuntu-1.jpg?resize=800%2C400&amp;ssl=1" alt="Select another wifi network in Ubuntu"></p><p>等待大概 5 秒鐘，看到其他可用的網絡。</p><p>現在，你就可以選擇你想要連接的網絡，點擊連接。這樣就完成了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>重啓網絡連接是每個 Linux 用户在使用過程中必須經歷的事情。</p><p>我們希望這些方法可以幫助你處理這樣的問題！</p><p>你是如何重啓或管理你的網絡的？我們是否還有遺漏的？請在下方留言。</p><hr>',22)),i("p",null,[t[15]||(t[15]=n("via: ",-1)),e(s,{href:"https://itsfoss.com/restart-network-ubuntu"},{default:o(()=>[...t[14]||(t[14]=[n("https://itsfoss.com/restart-network-ubuntu",-1)])]),_:1})]),i("p",null,[t[20]||(t[20]=n("作者：",-1)),e(s,{href:"https://itsfoss.com/author/sergiu/"},{default:o(()=>[...t[16]||(t[16]=[n("Sergiu",-1)])]),_:1}),t[21]||(t[21]=n(" 選題：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[17]||(t[17]=[n("lujun9972",-1)])]),_:1}),t[22]||(t[22]=n(" 譯者：",-1)),e(s,{href:"https://github.com/bodhix"},{default:o(()=>[...t[18]||(t[18]=[n("bodhix",-1)])]),_:1}),t[23]||(t[23]=n(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[19]||(t[19]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[26]||(t[26]=n("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[24]||(t[24]=[n("LCTT",-1)])]),_:1}),t[27]||(t[27]=n(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...t[25]||(t[25]=[n("Linux中國",-1)])]),_:1}),t[28]||(t[28]=n(" 榮譽推出",-1))])])}const x=a(d,[["render",m]]);export{C as __pageData,x as default};
